"""An AVL tree, provided for the comparison in compare.py. You do not edit this file.

The nodes are the same dicts as in bst.py with one extra key, 'height', which each node
keeps up to date so the tree can notice when one side gets too tall and rotate.
Insert is recursive. That is safe here because an AVL tree of n values is never taller
than about 1.44 * log2(n) levels.
"""


def create_avl_node(value):
    return {'payload': value, 'left': None, 'right': None, 'height': 0}


def height(node):
    return -1 if node is None else node['height']


def update_height(node):
    node['height'] = 1 + max(height(node['left']), height(node['right']))


def balance_factor(node):
    return height(node['left']) - height(node['right'])


def rotate_right(y):
    x = y['left']
    y['left'] = x['right']
    x['right'] = y
    update_height(y)                          # y is lower now, so fix it first
    update_height(x)
    return x                                  # x is the new root of this subtree


def rotate_left(x):
    y = x['right']
    x['right'] = y['left']
    y['left'] = x
    update_height(x)
    update_height(y)
    return y


def rebalance(node):
    update_height(node)
    bf = balance_factor(node)
    if bf > 1:                                # left side is too tall
        if balance_factor(node['left']) < 0:  # left-right case: straighten it first
            node['left'] = rotate_left(node['left'])
        return rotate_right(node)
    if bf < -1:                               # right side is too tall
        if balance_factor(node['right']) > 0: # right-left case
            node['right'] = rotate_right(node['right'])
        return rotate_left(node)
    return node


def avl_insert(node, value):
    if node is None:
        return create_avl_node(value)
    if value < node['payload']:
        node['left'] = avl_insert(node['left'], value)
    elif value > node['payload']:
        node['right'] = avl_insert(node['right'], value)
    else:
        return node                           # duplicate: nothing to do
    return rebalance(node)                    # runs on the way back up


def avl_search(root, value):
    """Return the node holding value, or None. Same as a plain BST search."""
    node = root
    while node is not None:
        if value == node['payload']:
            return node
        node = node['left'] if value < node['payload'] else node['right']
    return None
